<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
/** Provides workspace addon behavior within the WorkIntel application. */ class WorkspaceAddon extends Model{protected $fillable=['uuid','workspace_id','platform_addon_id','status','quantity','started_at','current_period_start','current_period_end','canceled_at','metadata'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['quantity'=>'decimal:4','started_at'=>'datetime','current_period_start'=>'datetime','current_period_end'=>'datetime','canceled_at'=>'datetime','metadata'=>'array'];}/** Handles the workspace operation for the current WorkIntel workflow. */ public function workspace():BelongsTo{return $this->belongsTo(Workspace::class);}/** Handles the addon operation for the current WorkIntel workflow. */ public function addon():BelongsTo{return $this->belongsTo(PlatformAddon::class,'platform_addon_id');}/** Handles the usage events operation for the current WorkIntel workflow. */ public function usageEvents():HasMany{return $this->hasMany(AddonUsageEvent::class);}}
